#[cfg(feature = "test-support")]
pub mod test_support {
    use std::future::{Future, ready};
    use std::pin::Pin;
    use std::sync::Arc;
    use ::boxology_contract::{
        CallContext, CapabilityId, ContractType, DecodeRole, Detail, ErasedCallError,
        ErasedCallTarget, SlotValue, TypeDescriptor,
    };
    use super::{
        CompleteError, MODEL_COMPLETION_COMPLETE, ModelCompletionHandle,
        conversion_detail,
    };
    type CompleteFuture = Pin<
        Box<
            dyn Future<
                Output = Result<super::CompletionOutcome, CompleteError>,
            > + Send + 'static,
        >,
    >;
    type CompleteResponder = dyn Fn(
        CallContext,
        super::CompletionRequest,
    ) -> CompleteFuture + Send + Sync + 'static;
    #[derive(Clone, Default)]
    pub struct ModelCompletionFake {
        complete: Option<Arc<CompleteResponder>>,
    }
    impl ModelCompletionFake {
        pub fn new() -> Self {
            Self::default()
        }
        pub fn with_complete<F, Fut>(mut self, responder: F) -> Self
        where
            F: Fn(CallContext, super::CompletionRequest) -> Fut + Send + Sync + 'static,
            Fut: Future<Output = Result<super::CompletionOutcome, CompleteError>> + Send
                + 'static,
        {
            self.complete = Some(
                Arc::new(move |context, request| {
                    Box::pin(responder(context, request))
                }),
            );
            self
        }
        pub fn handle(&self) -> ModelCompletionHandle {
            ModelCompletionHandle::from_erased(Arc::new(self.clone()))
        }
    }
    impl ErasedCallTarget for ModelCompletionFake {
        fn call<'a>(
            &'a self,
            capability: &'a CapabilityId,
            context: CallContext,
            input: SlotValue,
        ) -> Pin<
            Box<dyn Future<Output = Result<SlotValue, ErasedCallError>> + Send + 'a>,
        > {
            if capability != &*MODEL_COMPLETION_COMPLETE {
                return Box::pin(ready(Err(unprogrammed())));
            }
            let Some(responder) = self.complete.clone() else {
                return Box::pin(ready(Err(unprogrammed())));
            };
            Box::pin(async move {
                let input = TypeDescriptor::structure([
                        ::boxology_contract::FieldDescriptor::new(
                            "messages",
                            TypeDescriptor::list(
                                    TypeDescriptor::structure([
                                            ::boxology_contract::FieldDescriptor::new(
                                                "role",
                                                TypeDescriptor::enumeration([
                                                        ::boxology_contract::VariantDescriptor::new(
                                                            "System",
                                                            ::boxology_contract::VariantPayload::Unit,
                                                            None,
                                                        ),
                                                        ::boxology_contract::VariantDescriptor::new(
                                                            "User",
                                                            ::boxology_contract::VariantPayload::Unit,
                                                            None,
                                                        ),
                                                        ::boxology_contract::VariantDescriptor::new(
                                                            "Assistant",
                                                            ::boxology_contract::VariantPayload::Unit,
                                                            None,
                                                        ),
                                                        ::boxology_contract::VariantDescriptor::new(
                                                            "Tool",
                                                            ::boxology_contract::VariantPayload::Unit,
                                                            None,
                                                        ),
                                                    ])
                                                    .expect("generated enum descriptor is valid"),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "content",
                                                TypeDescriptor::optional(TypeDescriptor::string())
                                                    .expect("generated optional descriptor is valid"),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "tool_call_id",
                                                TypeDescriptor::optional(TypeDescriptor::string())
                                                    .expect("generated optional descriptor is valid"),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "name",
                                                TypeDescriptor::optional(TypeDescriptor::string())
                                                    .expect("generated optional descriptor is valid"),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "tool_calls",
                                                TypeDescriptor::list(
                                                        TypeDescriptor::structure([
                                                                ::boxology_contract::FieldDescriptor::new(
                                                                    "id",
                                                                    TypeDescriptor::string(),
                                                                    None,
                                                                ),
                                                                ::boxology_contract::FieldDescriptor::new(
                                                                    "name",
                                                                    TypeDescriptor::string(),
                                                                    None,
                                                                ),
                                                                ::boxology_contract::FieldDescriptor::new(
                                                                    "arguments_json",
                                                                    TypeDescriptor::string(),
                                                                    None,
                                                                ),
                                                            ])
                                                            .expect("generated struct descriptor is valid"),
                                                    )
                                                    .expect("generated list descriptor is valid"),
                                                None,
                                            ),
                                        ])
                                        .expect("generated struct descriptor is valid"),
                                )
                                .expect("generated list descriptor is valid"),
                            None,
                        ),
                        ::boxology_contract::FieldDescriptor::new(
                            "tools",
                            TypeDescriptor::list(
                                    TypeDescriptor::structure([
                                            ::boxology_contract::FieldDescriptor::new(
                                                "name",
                                                TypeDescriptor::string(),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "description",
                                                TypeDescriptor::string(),
                                                None,
                                            ),
                                            ::boxology_contract::FieldDescriptor::new(
                                                "input_schema_json",
                                                TypeDescriptor::string(),
                                                None,
                                            ),
                                        ])
                                        .expect("generated struct descriptor is valid"),
                                )
                                .expect("generated list descriptor is valid"),
                            None,
                        ),
                        ::boxology_contract::FieldDescriptor::new(
                            "max_output_tokens",
                            TypeDescriptor::optional(TypeDescriptor::u64())
                                .expect("generated optional descriptor is valid"),
                            None,
                        ),
                    ])
                    .expect("generated struct descriptor is valid")
                    .conform(DecodeRole::ProviderInput, input)
                    .map_err(|error| {
                        ErasedCallError::ContractViolation(
                            conversion_detail("input_decode", error),
                        )
                    })?;
                let request = <super::CompletionRequest as ContractType>::decode(&input)
                    .map_err(|error| {
                        ErasedCallError::ContractViolation(
                            conversion_detail("input_decode", error),
                        )
                    })?;
                match responder(context, request).await {
                    Ok(output) => {
                        output
                            .encode()
                            .map_err(|error| {
                                ErasedCallError::InvalidResponse(
                                    conversion_detail("output_encode", error),
                                )
                            })
                    }
                    Err(error) => Err(ErasedCallError::from_domain(&error)),
                }
            })
        }
    }
    fn unprogrammed() -> ErasedCallError {
        ErasedCallError::Internal(Detail::new("unprogrammed_capability"))
    }
}
